int getCellsPerSymbol(int fft_size, int reduced_carriers, int sp_pattern) {
    if (fft_size < 0 || fft_size > 2) return 0;
    if (reduced_carriers < 0 || reduced_carriers > 4) reduced_carriers = 0;
    if (sp_pattern < 0 || sp_pattern > 15) return 0;
    if (sp_pattern < 8)
        return TABLE_7_3_CELLS[fft_size][reduced_carriers][sp_pattern];
    else
        return TABLE_7_4_CELLS[fft_size][reduced_carriers][sp_pattern - 8];
}

int getSbsTotalDataCells(int fft_size, int reduced_carriers, int sp_pattern) {
    if (fft_size < 0 || fft_size > 2) return 0;
    if (reduced_carriers < 0 || reduced_carriers > 4) reduced_carriers = 0;
    if (sp_pattern < 0 || sp_pattern > 15) return 0;
    return SBS_TOTAL_DATA_CELLS[fft_size][reduced_carriers][sp_pattern];
}

int getSbsActiveCells(int fft_size, int reduced_carriers, int sp_pattern, int sp_boost) {
    if (fft_size < 0 || fft_size > 2) return 0;
    if (reduced_carriers < 0 || reduced_carriers > 4) reduced_carriers = 0;
    if (sp_pattern < 0 || sp_pattern > 15) return 0;
    if (sp_boost < 0 || sp_boost > 4) sp_boost = 0;
    switch (reduced_carriers) {
        case 0: return SBS_ACTIVE_CELLS_CRED0[fft_size][sp_boost][sp_pattern];
        case 1: return SBS_ACTIVE_CELLS_CRED1[fft_size][sp_boost][sp_pattern];
        case 2: return SBS_ACTIVE_CELLS_CRED2[fft_size][sp_boost][sp_pattern];
        case 3: return SBS_ACTIVE_CELLS_CRED3[fft_size][sp_boost][sp_pattern];
        case 4: return SBS_ACTIVE_CELLS_CRED4[fft_size][sp_boost][sp_pattern];
        default: return SBS_ACTIVE_CELLS_CRED0[fft_size][sp_boost][sp_pattern];
    }
}

